            if histories.len() != ids.len() || ids.iter().any(|id| !histories.contains_key(id)) {
                return Err(ImportError::Invalid(
                    "History response does not contain all requested member IDs".into(),
                ));
            }
            let mut members = Vec::new();
            for profile in profiles {
                let history = &histories[&profile.id];
                let is_current = current.contains_key(&profile.id);
                let member = Member::from_history(profile, history, term, as_of, is_current)?;
                if member.periods().is_empty() {
                    result.excluded_candidates += 1;
                } else {
                    members.push(member);
                }
            }
            let changes = store.member_batch(term, &members).await?;
            result.changes.inserted += changes.inserted;
            result.changes.updated += changes.updated;
            result.changes.unchanged += changes.unchanged;
            for member in members {
                result.members += 1;
                result.current_commons += usize::from(member.is_current());
                result.former_commons += usize::from(!member.is_current());
                result.service_periods += member.periods().len();
            }
            eprintln!("Committed member batch ({} processed total)", seen.len());
        }
        match page.next {
            Some(next) => offset = next,
            None => break,
        }
    }
    if current.keys().any(|id| !seen.contains_key(id)) {
        return Err(ImportError::Invalid(
            "Current search contains members missing from historical search".into(),
        ));
    }
    if result.members == 0 {
        return Err(ImportError::Invalid(
            "No Commons service was found for the configured term".into(),
        ));
    }
    Ok(result)
}

#[derive(Debug, Serialize)]
pub(crate) struct DeclarationSummary {
    pub status: &'static str,
    pub term_start: NaiveDate,
    pub members: usize,
    pub declarations: usize,
    pub rejected: usize,
    pub new_members: Vec<i32>,
}

struct EvidenceSet<'a, S> {
    source: &'a S,
    records: HashMap<i32, Evidence>,
}

impl<S: DeclarationSource> EvidenceSet<'_, S> {
    fn remember(&mut self, evidence: Evidence) -> Result<()> {
        if let Some(id) = evidence.id() {
            if let Some(previous) = self.records.get(&id) {
                if previous.payload != evidence.payload {
                    return Err(ImportError::Invalid(format!(
                        "Conflicting duplicate declaration {id}"
                    )));
                }
                eprintln!("Duplicate declaration {id}; identical source evidence collapsed");
            } else {
                self.records.insert(id, evidence);
            }
        }
        Ok(())
    }

    fn resolve<'a>(
        &'a mut self,
        evidence: &'a Evidence,
        member: i32,
        mut ancestors: HashSet<i32>,
    ) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<Declaration>> + Send + 'a>> {
        Box::pin(async move {
            let draft = self.source.interpret(evidence)?;
            if Some(draft.id) != evidence.id() || draft.member_source_id != member {
                return Err(ImportError::Rejected(
                    "Source identity or member mismatch".into(),
                ));
            }
            if !ancestors.insert(draft.id) {
                return Err(ImportError::Rejected("Cyclic parent relationship".into()));
            }
            let parent = if let Some(parent_id) = draft.required_parent() {
                if !self.records.contains_key(&parent_id) {
                    for record in self.source.parents(member, parent_id).await? {
                        self.remember(record)?;
                    }
                }
                let record = self.records.get(&parent_id).cloned().ok_or_else(|| {
                    ImportError::Rejected("Required parent was not returned".into())
                })?;
                Some(self.resolve(&record, member, ancestors).await?)
            } else {
                None
            };
            draft.accept(parent.as_ref())
        })
    }
}

pub(crate) async fn refresh_declarations(
    term: NaiveDate,
    as_of: NaiveDate,
    source: &(impl DeclarationSource + MemberSource),
    store: &impl ImportStore,
) -> Result<DeclarationSummary> {
    let cohort = store.cohort(term).await?;
    if cohort.is_empty() {
        return Err(ImportError::Invalid(
            "No stored Commons cohort for the configured term; initialize members first".into(),
        ));
    }
    let current = current_members(source, term, as_of).await?;
    let new_members = current
        .keys()
        .filter(|id| !cohort.contains_key(id))
        .copied()
        .collect();
    let mut result = DeclarationSummary {
        status: "succeeded",
        term_start: term,
        members: cohort.len(),
        declarations: 0,
        rejected: 0,
        new_members,
    };
    let mut sources = EvidenceSet {
        source,
        records: HashMap::new(),
    };
    let mut processed = HashSet::new();
    for (source_id, member_id) in cohort {
        let mut accepted = Vec::new();
        let mut offset = 0;
        loop {
            let page = source.declarations(source_id, offset).await?;
            for evidence in &page.entries {
                sources.remember(evidence.clone())?;
            }
            for evidence in page.entries {
                if evidence.id().is_some_and(|id| !processed.insert(id)) {
                    continue;
                }
                match sources.resolve(&evidence, source_id, HashSet::new()).await {
                    Ok(declaration) => accepted.push(Accepted {
                        declaration,
                        fetched_at: evidence.fetched_at,
                    }),
                    Err(ImportError::Rejected(reason)) => {
                        result.rejected += 1;
                        eprintln!(
                            "Rejected declaration {:?} (member {}, {}): {}",
                            evidence.id(),
                            source_id,
                            evidence.context,
                            reason
                        );
                    }
                    Err(error) => return Err(error),
                }
            }
            match page.next {
                Some(next) => offset = next,
                None => break,
            }
        }
        // No write becomes visible until all pages and necessary parents have succeeded.
        store.publish(member_id, &accepted).await?;
        result.declarations += accepted.len();
        eprintln!("Committed declarations for member {source_id}");
    }
    Ok(result)
}
use chrono::{DateTime, Duration, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

use super::{
    Result,
    ports::{DeclarationSource, ImportStore, MemberSource, NotificationQueue, Notifications},
    refresh::{refresh_declarations, refresh_members},
};

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "kebab-case")]
pub(crate) enum ImportKind {
    Members,
    Declarations,
    Initialize,
}

pub(crate) trait Clock: Send + Sync {
    fn now(&self) -> DateTime<Utc>;
}

pub(crate) async fn run_import(
    kind: ImportKind,
    term: NaiveDate,
    as_of: NaiveDate,
    source: &(impl MemberSource + DeclarationSource),
    store: &(impl ImportStore + NotificationQueue),
    clock: &impl Clock,
    notification_interval: Option<i64>,
    scheduled: bool,
) -> Result<Value> {
    let _lease = store.acquire().await?;
    let mut state = store.refresh_state(term).await?;
    let started = clock.now();
    if scheduled && !state.due(started) {
        return Ok(json!({"status":"not-due"}));
    }
    let members = match kind {
        ImportKind::Members | ImportKind::Initialize => {
            Some(refresh_members(term, as_of, source, store).await?)
        }
        ImportKind::Declarations => None,
    };
    if matches!(kind, ImportKind::Members) {
        return Ok(json!(members));
    }
    state.last_attempt = Some(started);
    state.next_attempt = Some(started); // Restart after an interrupted run is immediately due.
    store.record_refresh(term, &state).await?;
    let result = refresh_declarations(term, as_of, source, store).await;
    let ended = clock.now();
    match &result {
        Ok(summary) => state.completed(
            started,
            ended,
            summary.rejected,
            summary.new_members.clone(),
        ),
        Err(_) => state.failed(started, ended),
    }
    store.record_refresh(term, &state).await?;
    if let Err(error) = queue_refresh_notification(term, store, clock, notification_interval).await
    {
        eprintln!("Could not queue import notification: {error:?}");
    }
    let declarations = result?;
    Ok(if matches!(kind, ImportKind::Initialize) {
        json!({"status":"succeeded", "members":members, "declarations":declarations})
    } else {
        json!(declarations)
    })
}

pub(crate) async fn deliver_pending(
    queue: &impl NotificationQueue,
    notifications: &impl Notifications,
    clock: &impl Clock,
) -> Result<()> {
    if let Some((id, message, attempts)) = queue.pending(clock.now()).await? {
        match notifications.deliver(&message).await {
            Ok(()) => queue.delivered(id).await?,
            Err(error) => {
                eprintln!("Notification delivery failed: {error:?}");
                let seconds = 60_i64
                    .saturating_mul(2_i64.saturating_pow(attempts.clamp(0, 6) as u32))
                    .min(3600);
                queue
                    .retry_notification(id, clock.now() + Duration::seconds(seconds))
                    .await?;
            }
        }
    }
    Ok(())
}

// Retrying this operation is safe after queue storage failures: the interval key is unique.
pub(crate) async fn queue_refresh_notification(
    term: NaiveDate,
    store: &(impl ImportStore + NotificationQueue),
    clock: &impl Clock,
    interval: Option<i64>,
) -> Result<()> {
    let Some(interval) = interval.filter(|seconds| *seconds > 0) else {
        return Ok(());
    };
    let state = store.refresh_state(term).await?;
    let Some(outcome) = &state.outcome else {
        return Ok(());
    };
    let bucket = clock.now().timestamp().div_euclid(interval);
    let key = format!("refresh:{term}:{bucket}");
    let message = format!(
        "Exposed refresh: {outcome}. Last complete source check: {}. Rejected declarations: {}. New MPs awaiting manual refresh: {:?}.",
        state
            .last_completed
            .map_or_else(|| "never".into(), |d| d.to_rfc3339()),
        state.rejected,
        state.new_members
    );
    store.enqueue(&key, &message).await
}
//! Composition and lifecycle for source workers, operator API, and timers.
use anyhow::Context;
use chrono::{DateTime, Utc};
use sqlx::postgres::PgPoolOptions;
use std::{sync::Arc, time::Duration};

use super::{
    adapters::{
        parliament::{CliTransport, Parliament},
        postgres::PostgresStore,
        whatsapp::WhatsApp,
    },
    admin::{self, AdminState},
    config::ImportConfig,
    core::{
        ImportError,
        coordinator::{Clock, ImportKind, deliver_pending, queue_refresh_notification, run_import},
        ports::ImportStore,
    },
};

pub(crate) struct SystemClock;
impl Clock for SystemClock {
    fn now(&self) -> DateTime<Utc> {
        Utc::now()
    }
}

/// Run the import operator listener and the in-process daily refresh task.
///
/// # Errors
/// Returns a configuration, database connection, or listener error at startup.
/// Migrations remain an explicit operator action.
pub async fn serve(config: &ImportConfig, connection_string: &str) -> anyhow::Result<()> {
    let token = config
        .admin_token_env
        .as_ref()
        .map(|name| std::env::var(name))
        .transpose()
        .context("Operator token environment variable is missing")?;
    anyhow::ensure!(
        token.as_ref().is_none_or(|t| !t.is_empty()),
        "Operator token is empty"
    );
    anyhow::ensure!(
        config.admin_bind.ip().is_loopback() || token.is_some(),
        "A non-loopback operator listener requires an access token"
    );
    anyhow::ensure!(
        config.notification_interval_seconds.is_none_or(|n| n > 0),
        "Notification interval must be positive"
    );
    anyhow::ensure!(
        config.notification_interval_seconds.is_none() || config.whatsapp.is_some(),
        "A notification interval requires a WhatsApp adapter"
    );
    let whatsapp = config.whatsapp.clone().map(WhatsApp::new).transpose()?;
    let pool = PgPoolOptions::new()
        .max_connections(8)
        .acquire_timeout(Duration::from_secs(15))
        .connect(connection_string)
        .await?;
    let store = PostgresStore::new(pool);
    store.refresh_state(config.term_start).await?;
    let config = Arc::new(config.clone());
    let state = AdminState::new(store.clone(), config.clone(), token);
    let listener = tokio::net::TcpListener::bind(config.admin_bind).await?;
    let server = async {
        axum::serve(listener, admin::router(state.clone()))
            .await
            .map_err(anyhow::Error::from)
    };
    let refresh = async {
        let mut timer = tokio::time::interval(Duration::from_secs(60));
        timer.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            timer.tick().await;
            state.expire_sessions().await;
            if !config.automatic_refresh {
                continue;
            }
            let result = async {
                if !store
                    .refresh_state(config.term_start)
                    .await?
                    .due(Utc::now())
                {
                    return Ok(());
                }
                let source = Parliament(CliTransport::new(
                    config.python.clone(),
                    config.source_directory.clone(),
                ));
                let as_of = Utc::now()
                    .with_timezone(&chrono_tz::Europe::London)
                    .date_naive();
                run_import(
                    ImportKind::Declarations,
                    config.term_start,
                    as_of,
                    &source,
                    &store,
                    &SystemClock,
                    config.notification_interval_seconds,
                    true,
                )
                .await?;
                Ok::<_, ImportError>(())
            }
            .await;
            if let Err(error) = result {
                if !matches!(error, ImportError::Busy) {
                    eprintln!("Scheduled declaration refresh: {error:?}");
                }
            }
        }
        #[allow(unreachable_code)]
        Ok::<(), anyhow::Error>(())
    };
    let notifications = async {
        let mut timer = tokio::time::interval(Duration::from_secs(30));
        timer.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            timer.tick().await;
            if let Some(adapter) = &whatsapp {
                if let Err(error) = queue_refresh_notification(
                    config.term_start,
                    &store,
                    &SystemClock,
                    config.notification_interval_seconds,
                )
                .await
                {
                    eprintln!("Notification policy: {error:?}");
                }
                if let Err(error) = deliver_pending(&store, adapter, &SystemClock).await {
                    eprintln!("Notification queue: {error:?}");
                }
            }
        }
        #[allow(unreachable_code)]
        Ok::<(), anyhow::Error>(())
    };
    tokio::try_join!(server, refresh, notifications)?;
    Ok(())
}

