use std::{future::Future, path::PathBuf, process::Stdio, time::Duration};

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    process::{Child, ChildStdin, ChildStdout, Command},
    sync::Mutex,
};

use super::declarations::{interpret, source_date};
use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, Evidence},
    members::{HouseMembership, MemberHistory, MemberProfile},
    ports::{DeclarationSource, MemberSource, Page},
};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "operation", rename_all = "kebab-case")]
pub(crate) enum Request {
    CurrentMembers {
        offset: usize,
    },
    MemberCandidates {
        term_start: NaiveDate,
        as_of: NaiveDate,
        offset: usize,
    },
    MemberHistories {
        ids: Vec<i32>,
    },
    Declarations {
        member: i32,
        offset: usize,
    },
    Parent {
        member: i32,
        parent: i32,
    },
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub(crate) struct Response {
    pub payload: Value,
    pub fetched_at: DateTime<Utc>,
    pub context: String,
}

pub(crate) trait Transport: Send + Sync {
    fn fetch(&self, request: Request) -> impl Future<Output = Result<Response>> + Send;
}

pub(crate) struct Parliament<T>(pub T);

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Envelope {
    items: Vec<Value>,
    total_results: usize,
    #[serde(rename = "skip")]
    _skip: usize,
}

fn envelope(
    response: &Response,
    offset: usize,
    members: bool,
) -> Result<(Vec<Value>, Option<usize>)> {
    let page: Envelope = serde_json::from_value(response.payload.clone())
        .map_err(|e| ImportError::Invalid(format!("Invalid Parliament page: {e}")))?;
    if members && page.items.is_empty() && offset < page.total_results {
        return Err(ImportError::Invalid(
            "Search ended before all advertised members were returned".into(),
        ));
    }
    let next = offset
        .checked_add(page.items.len())
        .ok_or_else(|| ImportError::Invalid("Invalid page size".into()))?;
    let more = !page.items.is_empty() && next < page.total_results;
    Ok((page.items, more.then_some(next)))
}

#[derive(Deserialize)]
struct Party {
    id: Option<i32>,
    name: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Membership {
    house: i16,
    membership_from: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Profile {
    id: i32,
    name_display_as: String,
    latest_party: Option<Party>,
    latest_house_membership: Membership,
}

fn profile(raw: Value) -> Result<MemberProfile> {
    let p: Profile = serde_json::from_value(raw["value"].clone())
        .map_err(|e| ImportError::Invalid(format!("Invalid member: {e}")))?;
    let (party_id, party_name) = p.latest_party.map_or((None, None), |p| (p.id, p.name));
    let member = MemberProfile {
        id: p.id,
        name: p.name_display_as,
        party_id,
        party_name,
        house: p.latest_house_membership.house,
        membership_from: p.latest_house_membership.membership_from,
    };
    member.validate()?;
    Ok(member)
}

impl<T: Transport> MemberSource for Parliament<T> {
    async fn profiles(
        &self,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
        offset: usize,
    ) -> Result<Page<MemberProfile>> {
        let request = if current {
            Request::CurrentMembers { offset }
        } else {
            Request::MemberCandidates {
                term_start: term,
                as_of,
                offset,
            }
        };
        let response = self.0.fetch(request).await?;
        let (items, next) = envelope(&response, offset, true)?;
        Ok(Page {
            entries: items.into_iter().map(profile).collect::<Result<_>>()?,
            next,
        })
    }
    async fn histories(&self, ids: &[i32]) -> Result<Vec<MemberHistory>> {
        if ids.is_empty() || ids.len() > 100 {
            return Err(ImportError::Invalid(
                "History requests need between 1 and 100 IDs".into(),
            ));
        }
        let response = self
            .0
            .fetch(Request::MemberHistories { ids: ids.to_vec() })
            .await?;
        let items = response
            .payload
            .as_array()
            .ok_or_else(|| ImportError::Invalid("Invalid history envelope".into()))?;
        items
            .iter()
            .map(|item| {
                #[derive(Deserialize)]
                #[serde(rename_all = "camelCase")]
                struct History {
                    id: i32,
                    house_membership_history: Vec<Value>,
                }
                let history: History = serde_json::from_value(item["value"].clone())
                    .map_err(|e| ImportError::Invalid(format!("Invalid history: {e}")))?;
                let memberships = history
                    .house_membership_history
                    .iter()
                    .map(|m| {
                        let house = m["house"]
                            .as_i64()
                            .and_then(|h| i16::try_from(h).ok())
                            .filter(|h| [1, 2].contains(h))
                            .ok_or_else(|| ImportError::Invalid("Invalid history House".into()))?;
                        let start = source_date(&m["membershipStartDate"], "membershipStartDate")
                            .map_err(|e| ImportError::Invalid(e.to_string()))?;
                        let end = if m["membershipEndDate"].is_null() {
                            None
                        } else {
                            Some(
                                source_date(&m["membershipEndDate"], "membershipEndDate")
                                    .map_err(|e| ImportError::Invalid(e.to_string()))?,
                            )
                        };
                        Ok(HouseMembership { house, start, end })
                    })
                    .collect::<Result<Vec<_>>>()?;
                if history.id <= 0 || memberships.is_empty() {
                    return Err(ImportError::Invalid("Invalid member history".into()));
                }
                Ok(MemberHistory {
                    id: history.id,
                    memberships,
                })
            })
            .collect()
    }
}

fn evidence(items: Vec<Value>, response: &Response) -> Vec<Evidence> {
    items
        .into_iter()
        .map(|payload| Evidence {
            source_id: payload
                .get("id")
                .and_then(Value::as_i64)
                .and_then(|n| i32::try_from(n).ok()),
            payload,
            fetched_at: response.fetched_at,
            context: response.context.clone(),
        })
        .collect()
}

impl<T: Transport> DeclarationSource for Parliament<T> {
    async fn declarations(&self, member: i32, offset: usize) -> Result<Page<Evidence>> {
        let response = self
            .0
            .fetch(Request::Declarations { member, offset })
            .await?;
        let (items, next) = envelope(&response, offset, false)?;
        Ok(Page {
            entries: evidence(items, &response),
            next,
        })
    }
    async fn parents(&self, member: i32, parent: i32) -> Result<Vec<Evidence>> {
        let response = self.0.fetch(Request::Parent { member, parent }).await?;
        let (items, _) = envelope(&response, 0, false)?;
        Ok(evidence(items, &response))
    }
    fn interpret(&self, evidence: &Evidence) -> Result<Draft> {
        interpret(&evidence.payload)
    }
}

struct Worker {
    _child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
}
pub(crate) struct CliTransport {
    python: PathBuf,
    directory: PathBuf,
    worker: Mutex<Option<Worker>>,
}

impl CliTransport {
    pub fn new(python: PathBuf, directory: PathBuf) -> Self {
        Self {
            python,
            directory,
            worker: Mutex::new(None),
        }
    }
    fn start(&self) -> Result<Worker> {
        // Preserve the venv executable symlink: resolving it selects the base Python.
        let python = std::path::absolute(&self.python)
            .map_err(|e| ImportError::source_failure("Python executable is unavailable", e))?;
        let mut command = Command::new(python);
        command
            .args(["-m", "exposed", "source"])
            .current_dir(&self.directory)
            .env_clear()
            .env("PYTHONPATH", "src")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true);
        for key in [
            "PATH",
            "SSL_CERT_FILE",
            "HTTPS_PROXY",
            "HTTP_PROXY",
            "NO_PROXY",
        ] {
            if let Some(value) = std::env::var_os(key) {
                command.env(key, value);
            }
        }
        let mut child = command
            .spawn()
            .map_err(|e| ImportError::source_failure("Could not start Python API worker", e))?;
        let input = child
            .stdin
            .take()
            .ok_or_else(|| ImportError::Source("Worker stdin unavailable".into()))?;
        let output = BufReader::new(
            child
                .stdout
                .take()
                .ok_or_else(|| ImportError::Source("Worker stdout unavailable".into()))?,
        );
        Ok(Worker {
            _child: child,
            input,
            output,
        })
    }
}

impl Transport for CliTransport {
    async fn fetch(&self, request: Request) -> Result<Response> {
        tokio::time::timeout(Duration::from_secs(240), async {
            let mut slot = self.worker.lock().await;
            if slot.is_none() {
                *slot = Some(self.start()?);
            }
            let worker = slot
                .as_mut()
                .ok_or_else(|| ImportError::Source("Worker did not start".into()))?;
            let mut data = serde_json::to_vec(&request)
                .map_err(|e| ImportError::source_failure("Could not encode worker request", e))?;
            data.push(b'\n');
            worker
                .input
                .write_all(&data)
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            worker
                .input
                .flush()
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            let mut line = String::new();
            worker
                .output
                .read_line(&mut line)
                .await
                .map_err(|e| ImportError::source_failure("Worker output closed", e))?;
            let value: Value = serde_json::from_str(&line)
                .map_err(|e| ImportError::source_failure("Invalid worker response", e))?;
            if let Some(error) = value.get("error").and_then(Value::as_str) {
                return Err(ImportError::Source(error.to_owned()));
            }
            serde_json::from_value(value)
                .map_err(|e| ImportError::source_failure("Invalid evidence envelope", e))
        })
        .await
        .map_err(|e| ImportError::source_failure("Python API worker timed out", e))?
    }
}
use std::{collections::HashMap, str::FromStr};

use bigdecimal::BigDecimal;
use chrono::{DateTime, NaiveDate, NaiveDateTime};
use serde::Deserialize;
use serde_json::{Map, Value};

use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, FunderCandidates, Funding, funder_attribution, latest_version},
};

pub(crate) fn invalid(path: &str, value: &Value, message: &str) -> ImportError {
    ImportError::Rejected(format!("{path}: {message}; input={value}"))
}

pub(crate) fn source_date(value: &Value, path: &str) -> Result<NaiveDate> {
    let text = value
        .as_str()
        .ok_or_else(|| invalid(path, value, "expected an ISO date"))?;
    if let Ok(date) = NaiveDate::parse_from_str(text, "%Y-%m-%d") {
        return Ok(date);
    }
    if let Ok(date) = DateTime::parse_from_rfc3339(text) {
        return Ok(date.date_naive());
    }
    for format in ["%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S%.f"] {
        if let Ok(date) = NaiveDateTime::parse_from_str(text, format) {
            return Ok(date.date());
        }
    }
    Err(invalid(path, value, "expected an ISO date or datetime"))
}

fn positive(value: &Value, path: &str) -> Result<i32> {
    value
        .as_i64()
        .and_then(|n| i32::try_from(n).ok())
        .filter(|n| *n > 0)
        .ok_or_else(|| invalid(path, value, "expected a positive integer"))
}

fn nonblank(value: &Value, path: &str) -> Result<String> {
    value
        .as_str()
        .filter(|s| !s.trim().is_empty())
        .map(str::to_owned)
        .ok_or_else(|| invalid(path, value, "expected a nonblank string"))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Field {
    name: String,
    #[serde(rename = "type")]
    kind: Option<String>,
    type_info: Option<Map<String, Value>>,
    #[serde(default)]
    value: Value,
    values: Option<Vec<Vec<Field>>>,
}

impl Field {
    fn text(&self, path: &str) -> Result<Option<String>> {
        if self.value.is_null() {
            return Ok(None);
        }
        self.value
            .as_str()
            .map(|s| (!s.trim().is_empty()).then(|| s.to_owned()))
            .ok_or_else(|| invalid(path, &self.value, "expected a string"))
    }

    fn check_shape(&self, path: &str, allowed: bool, nested: bool) -> Result<()> {
        let currency = self
            .type_info
            .as_ref()
            .is_some_and(|m| m.contains_key("currencyCode"));
        let financial =
            ["Value", "PaymentType", "Donors"].contains(&self.name.as_str()) || currency;
        if financial
            && (!allowed || (currency && self.name != "Value") || (nested && self.name == "Donors"))
        {
            return Err(invalid(
                path,
                &self.value,
                "unsupported funding field or nesting",
            ));
        }
        for (i, group) in self.values.iter().flatten().enumerate() {
            if self.name == "Donors" && group.is_empty() {
                return Err(invalid(path, &self.value, "empty donor group"));
            }
            for (j, field) in group.iter().enumerate() {
                field.check_shape(
                    &format!("{path}.values.{i}.{j}.{}", field.name),
                    allowed && self.name == "Donors",
                    true,
                )?;
            }
        }
        Ok(())
    }
}

fn funding(fields: &[Field], path: &str, donor_group: bool) -> Result<Funding> {
    let index: HashMap<_, _> = fields
        .iter()
        .enumerate()
        .map(|(i, f)| (f.name.as_str(), (i, f)))
        .collect();
    if index.len() != fields.len() {
        return Err(ImportError::Rejected(format!(
            "{path}: repeated field names"
        )));
    }
    let text = |name: &str| -> Result<Option<String>> {
        match index.get(name) {
            Some((i, f)) => f.text(&format!("{path}.{i}.{name}.value")),
            None => Ok(None),
        }
    };
    let mut amount = None;
    let mut currency = None;
    if let Some((i, value)) = index.get("Value") {
        let location = format!("{path}.{i}.Value");
        if value.kind.as_deref() != Some("Decimal") {
            return Err(invalid(
                &location,
                &value.value,
                "expected Decimal monetary field",
            ));
        }
        if !value.value.is_null() {
            let raw = match &value.value {
                Value::String(text) => text.clone(),
                Value::Number(number) => {
                    let raw = number.to_string();
                    // Python accepts arbitrary-size JSON integers, but rejects JSON floats.
                    if raw.contains(['.', 'e', 'E']) {
                        return Err(invalid(&location, &value.value, "unsupported amount"));
                    }
                    raw
                }
                _ => return Err(invalid(&location, &value.value, "unsupported amount")),
            };
            let unsigned = raw.strip_prefix('-').unwrap_or(&raw);
            let parts: Vec<_> = unsigned.split('.').collect();
            if parts.len() > 2
                || parts
                    .iter()
                    .any(|p| p.is_empty() || !p.bytes().all(|c| c.is_ascii_digit()))
            {
                return Err(invalid(&location, &value.value, "unsupported amount"));
            }
            amount = Some(
                BigDecimal::from_str(&raw)
                    .map_err(|_| invalid(&location, &value.value, "unsupported amount"))?,
            );
        }
        if let Some(code) = value
            .type_info
            .as_ref()
            .and_then(|m| m.get("currencyCode"))
            .filter(|v| !v.is_null())
        {
            currency = Some(
                code.as_str()
                    .ok_or_else(|| invalid(&location, code, "expected a currency string"))?
                    .to_owned(),
            );
        }
    }
    let (funder_name, funder_kind, company_number) = funder_attribution(
        FunderCandidates {
            ultimate_payer: text("UltimatePayerName"),
            donor: text("DonorName"),
            payer: text("PayerName"),
            group_donor: if donor_group { text("Name") } else { Ok(None) },
        },
        text("DonorStatus"),
        text("DonorCompanyIdentifier"),
    )?;
    Ok(Funding {
        funder_name,
        funder_kind,
        company_number,
        amount,
        currency,
        payment_type: text("PaymentType")?,
    })
}

pub(crate) fn interpret(raw: &Value) -> Result<Draft> {
    let id = positive(&raw["id"], "id")?;
    let member_source_id = positive(
        &raw["registrant"]["memberDetail"]["id"],
        "registrant.memberDetail.id",
    )?;
    if raw["registrant"]["type"] != "Member" || raw["category"]["type"] != "Commons" {
        return Err(invalid(
            "registrant/category",
            raw,
            "expected a Commons Member declaration",
        ));
    }
    let category_id = positive(&raw["category"]["id"], "category.id")?;
    let category_name = nonblank(&raw["category"]["name"], "category.name")?;
    let parent_id = if raw["parentInterestId"].is_null() {
        None
    } else {
        Some(positive(&raw["parentInterestId"], "parentInterestId")?)
    };
    let versions = raw["versions"]
        .as_array()
        .ok_or_else(|| invalid("versions", &raw["versions"], "expected versions"))?;
    let published = versions
        .iter()
        .enumerate()
        .map(|(i, v)| {
            let date = source_date(
                &v["register"]["publishedDate"],
                &format!("versions.{i}.register.publishedDate"),
            )?;
            let mut content = v
                .as_object()
                .ok_or_else(|| invalid("versions", v, "expected version object"))?
                .clone();
            content.remove("register");
            content.remove("links");
            Ok((date, Value::Object(content)))
        })
        .collect::<Result<Vec<_>>>()?;
    let selected = latest_version(&published)?;
    let version = &versions[selected];
    let path = format!("versions.{selected}.fields");
    let fields: Vec<Field> = serde_json::from_value(version["fields"].clone())
        .map_err(|e| invalid(&path, &version["fields"], &e.to_string()))?;
    let mut entries = Vec::new();
    for (i, field) in fields.iter().enumerate() {
        field.check_shape(&format!("{path}.{i}.{}", field.name), true, false)?;
    }
    if fields
        .iter()
        .any(|f| ["Value", "PaymentType"].contains(&f.name.as_str()))
    {
        entries.push(funding(&fields, &path, false)?);
    }
    for (i, field) in fields
        .iter()
        .enumerate()
        .filter(|(_, f)| f.name == "Donors")
    {
        let groups = field
            .values
            .as_ref()
            .ok_or_else(|| invalid(&path, &field.value, "expected donor groups"))?;
        for (j, group) in groups.iter().enumerate() {
            entries.push(funding(
                group,
                &format!("{path}.{i}.Donors.values.{j}"),
                true,
            )?);
        }
    }
    let payer = funding(&fields, &path, false)?.funder_name;
    let mut ultimate_payer_differs = false;
    if parent_id.is_some() {
        if let Some(field) = fields.iter().find(|f| f.name == "IsUltimatePayerDifferent") {
            if !field.value.is_null() && !field.value.is_boolean() {
                return Err(invalid(&path, &field.value, "expected a boolean"));
            }
            ultimate_payer_differs = field.value == true;
        }
    }
    let registration_date = if version["registrationDate"].is_null() {
        None
    } else {
        Some(source_date(
            &version["registrationDate"],
            "registrationDate",
        )?)
    };
    Ok(Draft {
        id,
        member_source_id,
        category_id,
        category_name,
        registration_date,
        funding: entries,
        payer,
        parent_id,
        ultimate_payer_differs,
    })
}

