 31	impl ImportStore for PostgresStore {
 32	    type Lease = PoolConnection<Postgres>;
 33	    async fn acquire(&self) -> Result<Self::Lease> {
 34	        let mut connection = self.pool.acquire().await.map_err(database)?;
 35	        let acquired: bool = sqlx::query_scalar("SELECT pg_try_advisory_lock(20260925, 1)")
 36	            .fetch_one(&mut *connection)
 37	            .await
 38	            .map_err(database)?;
 39	        if !acquired {
 40	            return Err(ImportError::Busy);
 41	        }
 42	        // Session locks must never be returned to the pool. Closing also handles cancellation.
 43	        connection.close_on_drop();
 44	        Ok(connection)
 45	    }
 46	
 47	    async fn member_batch(&self, term: NaiveDate, members: &[Member]) -> Result<Changes> {
 48	        let mut tx = self.pool.begin().await.map_err(database)?;
 49	        let dates: Vec<DateTime<Utc>> =
 50	            sqlx::query_scalar("SELECT term_start FROM exposed.parliament_terms")
 51	                .fetch_all(&mut *tx)
 52	                .await
 53	                .map_err(database)?;
 54	        validate_configured_term(term, dates.into_iter().map(|d| d.date_naive()))?;
 55	        let term_id: Uuid = sqlx::query_scalar("INSERT INTO exposed.parliament_terms (term_start) VALUES ($1) ON CONFLICT (term_start) DO UPDATE SET term_start = EXCLUDED.term_start RETURNING id")
 56	            .bind(midnight(term)).fetch_one(&mut *tx).await.map_err(database)?;
 57	        let mut changes = Changes::default();
 58	        for member in members {
 59	            let p = member.profile();
 60	            let previous = sqlx::query("SELECT name, party_id, party_name, latest_house, latest_membership_from, is_current_commons FROM exposed.members WHERE parliament_member_id = $1")
 61	                .bind(p.id).fetch_optional(&mut *tx).await.map_err(database)?;
 62	            match previous {
 63	                None => changes.inserted += 1,
 64	                Some(row)
 65	                    if row.get::<String, _>("name") == p.name
 66	                        && row.get::<Option<i32>, _>("party_id") == p.party_id
 67	                        && row.get::<Option<String>, _>("party_name") == p.party_name
 68	                        && row.get::<i16, _>("latest_house") == p.house
 69	                        && row.get::<Option<String>, _>("latest_membership_from")
 70	                            == p.membership_from
 71	                        && row.get::<bool, _>("is_current_commons") == member.is_current() =>
 72	                {
 73	                    changes.unchanged += 1
 74	                }
 75	                Some(_) => changes.updated += 1,
 76	            }
 77	            let member_id: Uuid = sqlx::query_scalar("INSERT INTO exposed.members (parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons) VALUES ($1,$2,$3,$4,$5,$6,$7) ON CONFLICT (parliament_member_id) DO UPDATE SET name=EXCLUDED.name, party_id=EXCLUDED.party_id, party_name=EXCLUDED.party_name, latest_house=EXCLUDED.latest_house, latest_membership_from=EXCLUDED.latest_membership_from, is_current_commons=EXCLUDED.is_current_commons RETURNING id")
 78	                .bind(p.id).bind(&p.name).bind(p.party_id).bind(&p.party_name).bind(p.house).bind(&p.membership_from).bind(member.is_current())
 79	                .fetch_one(&mut *tx).await.map_err(database)?;
 80	            for period in member.periods() {
 81	                sqlx::query("INSERT INTO exposed.member_terms (member_id,term_id,house,source_start_date,source_end_date,served_from,served_until) VALUES ($1,$2,1,$3,$4,$5,$4) ON CONFLICT (member_id,term_id,house,source_start_date) DO UPDATE SET source_end_date=EXCLUDED.source_end_date, served_from=EXCLUDED.served_from, served_until=EXCLUDED.served_until")
 82	                    .bind(member_id).bind(term_id).bind(midnight(period.source_start)).bind(period.end.map(midnight)).bind(midnight(period.served_from))
 83	                    .execute(&mut *tx).await.map_err(database)?;
 84	            }
 85	            let starts: Vec<_> = member
 86	                .periods()
 87	                .iter()
 88	                .map(|p| midnight(p.source_start))
 89	                .collect();
 90	            sqlx::query("DELETE FROM exposed.member_terms WHERE member_id=$1 AND term_id=$2 AND NOT (source_start_date = ANY($3))")
 91	                .bind(member_id).bind(term_id).bind(starts).execute(&mut *tx).await.map_err(database)?;
 92	        }
 93	        tx.commit().await.map_err(database)?;
 94	        Ok(changes)
 95	    }
 96	
 97	    async fn cohort(&self, term: NaiveDate) -> Result<BTreeMap<i32, Uuid>> {
 98	        let rows = sqlx::query("SELECT DISTINCT m.id,m.parliament_member_id FROM exposed.members m JOIN exposed.member_terms s ON s.member_id=m.id JOIN exposed.parliament_terms t ON t.id=s.term_id WHERE t.term_start=$1 AND s.house=1 ORDER BY m.parliament_member_id")
 99	            .bind(midnight(term)).fetch_all(&self.pool).await.map_err(database)?;
100	        Ok(rows
101	            .into_iter()
102	            .map(|r| (r.get("parliament_member_id"), r.get("id")))
103	            .collect())
104	    }
105	
106	    async fn publish(&self, member: Uuid, declarations: &[Accepted]) -> Result<()> {
107	        let mut tx = self.pool.begin().await.map_err(database)?;
108	        for accepted in declarations {
109	            write_declaration(&mut tx, member, accepted).await?;
110	        }
111	        tx.commit().await.map_err(database)
112	    }
113	
114	    async fn refresh_state(&self, term: NaiveDate) -> Result<RefreshState> {
115	        let row = sqlx::query("SELECT * FROM exposed.import_refresh_state WHERE term_start=$1")
116	            .bind(midnight(term))
117	            .fetch_optional(&self.pool)
118	            .await
119	            .map_err(database)?;
120	        Ok(row.map_or_else(RefreshState::default, |r| RefreshState {
121	            last_completed: r.get("last_completed"),
122	            last_attempt: r.get("last_attempt"),
123	            next_attempt: r.get("next_attempt"),
124	            outcome: r.get("outcome"),
125	            rejected: r.get::<i32, _>("rejected") as usize,
126	            failures: r.get::<i32, _>("failures") as u32,
127	            new_members: r.get("new_members"),
128	        }))
129	    }
130	    async fn record_refresh(&self, term: NaiveDate, state: &RefreshState) -> Result<()> {
131	        sqlx::query("INSERT INTO exposed.import_refresh_state (term_start,last_completed,last_attempt,next_attempt,outcome,rejected,failures,new_members) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT (term_start) DO UPDATE SET last_completed=EXCLUDED.last_completed,last_attempt=EXCLUDED.last_attempt,next_attempt=EXCLUDED.next_attempt,outcome=EXCLUDED.outcome,rejected=EXCLUDED.rejected,failures=EXCLUDED.failures,new_members=EXCLUDED.new_members")
132	            .bind(midnight(term)).bind(state.last_completed).bind(state.last_attempt).bind(state.next_attempt).bind(&state.outcome)
133	            .bind(i32::try_from(state.rejected).unwrap_or(i32::MAX)).bind(i32::try_from(state.failures).unwrap_or(i32::MAX)).bind(&state.new_members)
134	            .execute(&self.pool).await.map_err(database)?;
135	        Ok(())
136	    }
137	}
