139	async fn write_funder(tx: &mut Transaction<'_, Postgres>, entry: &Funding) -> Result<Option<Uuid>> {
140	    let Some(name) = &entry.funder_name else {
141	        return Ok(None);
142	    };
143	    let previous = sqlx::query(
144	        "SELECT funder_kind,company_number FROM exposed.funders WHERE funder_name=$1 FOR UPDATE",
145	    )
146	    .bind(name)
147	    .fetch_optional(&mut **tx)
148	    .await
149	    .map_err(database)?;
150	    let (kind, number) = previous.map_or((None, None), |r| {
151	        (r.get("funder_kind"), r.get("company_number"))
152	    });
153	    let (kind, number) = merge_funder_metadata(entry, kind, number);
154	    let id = sqlx::query_scalar("INSERT INTO exposed.funders (funder_name,funder_kind,company_number) VALUES ($1,$2,$3) ON CONFLICT (funder_name) DO UPDATE SET funder_kind=EXCLUDED.funder_kind,company_number=EXCLUDED.company_number RETURNING id")
155	        .bind(name).bind(kind).bind(number).fetch_one(&mut **tx).await.map_err(database)?;
156	    Ok(Some(id))
157	}
158	
159	async fn write_declaration(
160	    tx: &mut Transaction<'_, Postgres>,
161	    member: Uuid,
162	    accepted: &Accepted,
163	) -> Result<()> {
164	    let d = accepted.declaration.draft();
165	    sqlx::query("INSERT INTO exposed.declarations (source_declaration_id,member_id,category_id,category_name,registration_date,fetched_at) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (source_declaration_id) DO UPDATE SET member_id=EXCLUDED.member_id,category_id=EXCLUDED.category_id,category_name=EXCLUDED.category_name,registration_date=EXCLUDED.registration_date,fetched_at=EXCLUDED.fetched_at")
166	        .bind(d.id).bind(member).bind(d.category_id).bind(&d.category_name).bind(d.registration_date.map(midnight)).bind(accepted.fetched_at)
167	        .execute(&mut **tx).await.map_err(database)?;
168	    let mut payments = Vec::new();
169	    for entry in &d.funding {
170	        payments.push(Payment {
171	            funder_id: write_funder(tx, entry).await?,
172	            amount: entry.amount.clone(),
173	            currency: entry.currency.clone(),
174	            payment_type: entry.payment_type.clone(),
175	        });
176	    }
177	    let rows = sqlx::query("SELECT funder_id,amount,currency,payment_type FROM exposed.funding_entries WHERE source_declaration_id=$1")
178	        .bind(d.id).fetch_all(&mut **tx).await.map_err(database)?;
179	    let previous: Vec<_> = rows
180	        .into_iter()
181	        .map(|r| Payment {
182	            funder_id: r.get("funder_id"),
183	            amount: r.get("amount"),
184	            currency: r.get("currency"),
185	            payment_type: r.get("payment_type"),
186	        })
187	        .collect();
188	    if same_payments(&payments, &previous) {
189	        return Ok(());
190	    }
191	    sqlx::query("DELETE FROM exposed.funding_entries WHERE source_declaration_id=$1")
192	        .bind(d.id)
193	        .execute(&mut **tx)
194	        .await
195	        .map_err(database)?;
196	    for p in payments {
197	        sqlx::query("INSERT INTO exposed.funding_entries (source_declaration_id,funder_id,amount,currency,payment_type) VALUES ($1,$2,$3,$4,$5)")
198	            .bind(d.id).bind(p.funder_id).bind(p.amount).bind(p.currency).bind(p.payment_type).execute(&mut **tx).await.map_err(database)?;
199	    }
200	    Ok(())
201	}
202	
203	impl NotificationQueue for PostgresStore {
204	    async fn enqueue(&self, key: &str, message: &str) -> Result<()> {
205	        sqlx::query("INSERT INTO exposed.import_notifications (event_key,message) VALUES ($1,$2) ON CONFLICT (event_key) DO NOTHING")
206	            .bind(key).bind(message).execute(&self.pool).await.map_err(database)?;
207	        Ok(())
208	    }
209	    async fn pending(&self, now: DateTime<Utc>) -> Result<Option<(Uuid, String, i32)>> {
210	        let row = sqlx::query("UPDATE exposed.import_notifications SET next_attempt=$1 + INTERVAL '2 minutes' WHERE id=(SELECT id FROM exposed.import_notifications WHERE delivered_at IS NULL AND next_attempt <= $1 ORDER BY next_attempt,id FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING id,message,attempts")
211	            .bind(now).fetch_optional(&self.pool).await.map_err(database)?;
212	        Ok(row.map(|r| (r.get("id"), r.get("message"), r.get("attempts"))))
213	    }
214	    async fn delivered(&self, id: Uuid) -> Result<()> {
215	        sqlx::query("UPDATE exposed.import_notifications SET delivered_at=now() WHERE id=$1")
216	            .bind(id)
217	            .execute(&self.pool)
218	            .await
219	            .map_err(database)?;
220	        Ok(())
221	    }
222	    async fn retry_notification(&self, id: Uuid, next: DateTime<Utc>) -> Result<()> {
223	        sqlx::query("UPDATE exposed.import_notifications SET attempts=attempts+1,next_attempt=$2 WHERE id=$1")
224	            .bind(id).bind(next).execute(&self.pool).await.map_err(database)?;
225	        Ok(())
226	    }
227	}

